EXTRA = {'fieldname': 'History and Change', 'fieldwhy': 'why the first cities grew where they grew, and how anybody knows', 'fieldwords': [('century', 'a hundred years'), ('ancient', 'very old, from a long time back'), ('empire', 'many countries under one king'), ('king', 'the man over a country in the old world'), ('war', 'fighting between two countries'), ('farming', 'growing food in a field'), ('stone', 'hard rock, cut for building'), ('wall', 'the side of a building, or a long one round a city'), ('writing', 'words on paper, stone or clay'), ('record', 'writing that keeps a fact for later'), ('ruins', 'the old walls and floors still in the ground'), ('evidence', 'the things that show you something is true')], 'r4': {'sub': 'Why the first cities grew', 'title': 'A City Is What Extra Food Looks Like', 'skill': ('A passage that answers one why', ['A history passage often opens with the world before the change.', 'Then it names the change. Here it is one word: farming.', 'Everything after that is what the change made possible.', 'A question with why wants the change, not the list after it.']), 'paras': ['Ten thousand years ago there were no cities anywhere on Earth. Everybody walked, and everybody looked for food every day. A person with no farm looks for food all day and has no time for anything else.', 'Then people started farming. A family with a field grew food for ten families. So nine families did something else. One built a house, one cut stone, one kept the records, and one was a king. That is what a city is: a place full of people and very few farms.', 'The first cities grew in the places with good land and easy water. Food came in from the land, and stone and shoes went out from the city. A wall went round the whole thing, because a city with food in it is a city somebody wants. Some of those ancient walls are still there.'], 'guided': [('How many cities were there ten thousand years ago?', ('ten', 'a few', 'none', 'nine'), 2, 'Ten thousand years ago there were no cities anywhere on Earth.'), ('What did everybody do every day?', ('walked to a city', 'looked for food', 'built a house', 'kept records'), 1, 'Everybody walked, and everybody looked for food every day.'), ('How much food did a family with a field grow?', ('food for one family', 'food for ten families', 'no food', 'food for a king'), 1, 'A family with a field grew food for ten families.')], 'exam': [('How many families did something else?', ('one', 'two', 'nine', 'ten'), 2, 'So nine families did something else.'), ('What is a city, for this writer?', ('a place with many walls', 'a place full of people and very few farms', 'a place with a king', 'a place with good water'), 1, 'That is what a city is: a place full of people and very few farms.'), ('Where did the first cities grow?', ('on high land', 'in the places with good land and easy water', 'near a wall', 'far from water'), 1, 'The first cities grew in the places with good land and easy water.'), ('Why did a wall go round the city?', ('to keep the people out', 'because a city with food in it is a city somebody wants', 'to carry the stone', 'because the king lived there'), 1, 'Because a city with food in it is a city somebody wants.')], 'words': 143}, 'r5': {'sub': 'How we know', 'title': 'Three Kinds of Evidence', 'skill': ('A numbered answer', ['When a writer says there are three kinds, the passage has three parts.', 'Find first, second and third and mark them.', 'Each part gets one example. The example is what the questions use.', 'A question with how many wants the number, not the parts.']), 'paras': ['Nobody wrote the story of the first cities down. There was no writing yet. So how does anybody know any of this? The answer is a good one.', 'There are three kinds of evidence. The first is the ruins. The walls and the floors are still in the ground, and a wall tells you how big the city was. The second is the things people threw away. A cup with old food in it tells you what the people ate. And the third kind is writing.', 'Writing came late and it changed everything. The first records were not stories. They were lists: so much food, so many animals, and a name at the end. A city needs writing, because nobody remembers four thousand animals.'], 'guided': [('Who wrote the story of the first cities down?', ('a king', 'the farms', 'nobody', 'the city'), 2, 'Nobody wrote the story of the first cities down.'), ('How many kinds of evidence are there?', ('two', 'three', 'four', 'ten'), 1, 'There are three kinds of evidence.'), ('What is the first kind?', ('writing', 'the ruins', 'the things people threw away', 'the animals'), 1, 'The first is the ruins.')], 'exam': [('What does a wall tell you?', ('what the people ate', 'how big the city was', 'who the king was', 'how many animals there were'), 1, 'A wall tells you how big the city was.'), ('What does a cup with old food in it tell you?', ('how big the city was', 'what the people ate', 'the name of the king', 'when writing came'), 1, 'A cup with old food in it tells you what the people ate.'), ('What were the first records?', ('stories', 'lists', 'walls', 'cups'), 1, 'The first records were not stories. They were lists.'), ('Why does a city need writing?', ('to keep the walls up', 'because nobody remembers four thousand animals', 'to grow food', 'because the king asked for it'), 1, 'A city needs writing, because nobody remembers four thousand animals.')], 'words': 124}, 'l4': {'sub': 'Why the first cities grew', 'caption': 'A short talk about the first cities', 'board': ['BEFORE FARMING', 'food for one person', 'AFTER FARMING', 'food for ten → nine free'], 'skill': ('A speaker who corrects an answer', ['A talk can open with a student’s wrong answer. It is not the point.', 'Listen for that is not the reason. The real reason comes next.', 'Here the real reason is one word, and the speaker repeats it.', 'The last two sentences are usually the whole talk in short.']), 'warm': [('Why did the first cities grow?', ('Because of food.', 'Ten thousand years.', 'Yes, they did.', 'In a field.'), 0, 'Why asks for a reason.'), ('Did people live together before farming?', ('Yes, they did.', 'In a city.', 'Food for ten.', 'Yes, they do.'), 0, 'Did ...? takes did or did not.')], 'script': [('Woman', 'I asked my class last year why the first cities grew where they grew. Somebody said, because people wanted to live together. But people always wanted that. That is not the reason. The reason is food. Before farming, one person looked for food all day and found food for one person. After farming, one person worked a field and grew food for ten. So nine people out of ten were free. One made a cup, one cut a stone, one kept a record, and one was a king. A city is not a lot of houses. A city is what extra food looks like.')], 'items': [('What did somebody in the class say?', ('because of food', 'because people wanted to live together', 'because of the king', 'because of farming'), 1, 'Somebody said, because people wanted to live together.'), ('What is the real reason?', ('the king', 'food', 'the walls', 'the cups'), 1, 'That is not the reason. The reason is food.'), ('How much food did one person find before farming?', ('food for one person', 'food for ten', 'no food', 'food for nine'), 0, 'One person looked for food all day and found food for one person.'), ('What is a city, for this speaker?', ('a lot of houses', 'what extra food looks like', 'a wall and a king', 'a field'), 1, 'A city is not a lot of houses. A city is what extra food looks like.')]}, 'l5': {'sub': 'How we know', 'caption': 'A short talk about evidence', 'board': ['HOW DO WE KNOW?', '1 ruins · a wall after 6,000 years', '2 what people threw away', '3 writing — but it came late'], 'skill': ('A list you must keep in order', ['First, second and third are a gift: they tell you how many notes.', 'Write the number and two or three words. Nothing else.', 'The speaker gives one example for each. Keep the examples apart.', 'The last sentence is often the surprise, not the summary.']), 'warm': [('How do we know about the first cities?', ('From three things.', 'Six thousand years.', 'Yes, we do.', 'A list of animals.'), 0, 'How do we know asks for the source, not a number of years.'), ('Did anybody write it down at the time?', ('No, nobody did.', 'A cup.', 'Three things.', 'Yes, they do.'), 0, 'Did ...? takes did or did not.')], 'script': [('Man', 'Students ask me how we know. It is a fair question, because nobody wrote any of this down at the time. We know from three things. First, the ruins: a wall is still a wall after six thousand years. Second, the things people threw away. That is the part of the work I like. A cup of old food tells you what a whole street ate for dinner. And third, writing. But writing came late. The first writing in the world was not a story. It was a list of animals. Nothing else at all.')], 'items': [('Why is it a fair question?', ('the ruins are gone', 'nobody wrote any of it down at the time', 'the cups are broken', 'writing came early'), 1, 'Nobody wrote any of this down at the time.'), ('How long is a wall still a wall?', ('six hundred years', 'six thousand years', 'a century', 'ten years'), 1, 'A wall is still a wall after six thousand years.'), ('What does a cup of old food tell you?', ('how old the city was', 'what a whole street ate for dinner', 'who the king was', 'how many animals there were'), 1, 'A cup of old food tells you what a whole street ate for dinner.'), ('What was the first writing in the world?', ('a story', 'a list of animals', 'a record of a war', 'a wall'), 1, 'The first writing in the world was not a story. It was a list of animals.')]}, 'w4': {'sub': 'Why the first cities grew', 'skill': ('Questions in the past simple', ['Did goes in front of the person, and the verb goes back to its plain form.', 'When did people start? not When did people started?', 'A question word goes first: Where did the cities grow?', 'With who as the subject there is no did: Who wrote it down?']), 'guided': [('People started farming ten thousand years ago.', ['when', 'did', 'people', 'start', 'farming', 'in that country'], 'When did people start farming in that country?'), ('A family grew food for ten families.', ['how much', 'food', 'did', 'a family', 'grow', 'for the city'], 'How much food did a family grow for the city?')], 'exam': [('The first cities grew near good land.', ['where', 'did', 'the first cities', 'grow', 'in that', 'country'], 'Where did the first cities grow in that country?'), ('Nobody wrote the story down.', ['who', 'wrote', 'the story', 'of the first', 'cities', 'down'], 'Who wrote the story of the first cities down?'), ('The people threw the cups away.', ['what', 'did', 'the people', 'throw', 'away', 'in the city'], 'What did the people throw away in the city?'), ('Writing came late.', ['when', 'did', 'writing', 'come', 'to the first', 'cities'], 'When did writing come to the first cities?')]}, 'w5': {'sub': 'How we know', 'prof': 'Dr Hartley', 'target': 75, 'question': 'A building company wants to build forty houses on a field with ancient ruins under it. The city has got very few rooms for students. What do you think the city must do? Give one reason.', 'posts': [('Mei', 'w', 'The ruins were there for six thousand years and they can wait another ten. Students need rooms now. But open the field first and keep the evidence, and then build.'), ('Ana', 'w', 'I am not happy with that. We opened a field like this one in my country and the walls went into a glass case in the college. The case is good, but the city is a different city now.')], 'skill': ('Two good answers and one choice', ['Mei and Ana both care about the ruins. They want different ends.', 'Say which one you take, and say what you give up.', 'Use the passage: ruins are evidence, and evidence goes once.', 'Seventy-five words is about seven sentences.']), 'starters': ['I agree with Mei, because ...', 'Ana is right that ...', 'The passage says the ruins ...', 'So the city must ...'], 'model': ['I agree with Mei. Students need rooms now, and the city cannot keep every old field for ever.', 'But Ana is right that you only dig a field once. The passage says the ruins are evidence, and evidence does not come back.', 'So the city must open the whole field first and pay for it. Then it can build the forty houses. That costs a year, and a year is not a high price for six thousand of them.'], 'model_words': 79}}
